/* @lc app=leetcode id=2876 lang=kotlin */
class Solution { fun countVisitedNodes(edges: List<Int>): IntArray = IntArray(edges.size).let { res -> IntArray(edges.size).let { step -> Array<((Int, Int) -> Int)?>(1) { null }.also { box -> box[0] = { u, d -> if (res[u] > 0) res[u] else if (step[u] > 0) (d - step[u]).also { len -> generateSequence(u) { edges[it] }.take(len).forEach { res[it] = len } } else d.also { step[u] = it }.let { box[0]!!(edges[u], d + 1) }.let { r -> if (res[u] == 0) (r + 1).also { res[u] = it } else res[u] } } }.also { box -> edges.indices.forEach { i -> box[0]!!(i, 1) } }.let { res } } }